    static class Program
    {
        [DllImport("shell32.dll", SetLastError = true)]
        private static extern void SetCurrentProcessExplicitAppUserModelID([MarshalAs(UnmanagedType.LPWStr)] string AppID);

        [STAThread]
        static void Main()
        {
            try
            {
                SetCurrentProcessExplicitAppUserModelID("Soikot.ClientProjectFolderGenerator.2");
            }
            catch {}

            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            Application.Run(new MainForm());
        }
    }

    public static class AppAssets
    {
        public static string EmbeddedIconBase64 = "";

        private static Icon appIconInstance = null;

        public static Icon GetAppIcon()
        {
            if (appIconInstance != null) return appIconInstance;
            try
            {
                byte[] bytes = Convert.FromBase64String(EmbeddedIconBase64);
                using (MemoryStream ms = new MemoryStream(bytes))
                {
                    appIconInstance = new Icon(ms);
                    return appIconInstance;
                }
            }
            catch
            {
                try
                {
                    appIconInstance = Icon.ExtractAssociatedIcon(Application.ExecutablePath);
                    return appIconInstance;
                }
                catch { return null; }
            }
        }
    }

