    public class CustomMenuRenderer : ToolStripProfessionalRenderer
    {
        private AppTheme currentTheme;

        public CustomMenuRenderer(AppTheme theme) : base(new CustomColorTable(theme))
        {
            this.currentTheme = theme;
        }

        protected override void OnRenderItemText(ToolStripItemTextRenderEventArgs e)
        {
            if (e.Item.Selected || e.Item.Pressed)
            {
                e.TextColor = currentTheme.AccentColor != Color.Empty ? currentTheme.AccentColor : currentTheme.TextPrimary;
            }
            else
            {
                e.TextColor = currentTheme.MenuText;
            }
            base.OnRenderItemText(e);
        }

        protected override void OnRenderMenuItemBackground(ToolStripItemRenderEventArgs e)
        {
            if (e.Item.Selected || e.Item.Pressed)
            {
                Rectangle rc = new Rectangle(Point.Empty, e.Item.Size);
                using (SolidBrush b = new SolidBrush(currentTheme.ButtonSecondaryBg))
                {
                    e.Graphics.FillRectangle(b, rc);
                }
            }
            else
            {
                base.OnRenderMenuItemBackground(e);
            }
        }
    }

