    }

    public static class UpdateManager
    {
        public const string CURRENT_VERSION = "2.0.0";
        public const string DEFAULT_UPDATE_URL = "https://raw.githubusercontent.com/soikot/Client-Project-Folder-Generator/main/version.json";

        public static UpdateInfo ParseJson(string json)
        {
            UpdateInfo info = new UpdateInfo();
            try
            {
                Match mV = Regex.Match(json, "\"version\"\\s*:\\s*\"(.*?)\"");
                if (mV.Success) info.Version = mV.Groups[1].Value.Trim();

                Match mCode = Regex.Match(json, "\"versionCode\"\\s*:\\s*(\\d+)");
                if (mCode.Success)
                {
                    int c;
                    if (int.TryParse(mCode.Groups[1].Value, out c)) info.VersionCode = c;
                }

                Match mDate = Regex.Match(json, "\"releaseDate\"\\s*:\\s*\"(.*?)\"");
                if (mDate.Success) info.ReleaseDate = mDate.Groups[1].Value.Trim();

                Match mTitle = Regex.Match(json, "\"title\"\\s*:\\s*\"(.*?)\"");
                if (mTitle.Success) info.Title = mTitle.Groups[1].Value.Trim();

                Match mUrl = Regex.Match(json, "\"downloadUrl\"\\s*:\\s*\"(.*?)\"");
                if (mUrl.Success) info.DownloadUrl = mUrl.Groups[1].Value.Trim();

                Match mLog = Regex.Match(json, "\"changelog\"\\s*:\\s*\\[(.*?)\\]", RegexOptions.Singleline);
                if (mLog.Success)
                {
                    MatchCollection mc = Regex.Matches(mLog.Groups[1].Value, "\"(.*?)\"");
                    foreach (Match m in mc)
                    {
                        info.Changelog.Add(Regex.Unescape(m.Groups[1].Value));
                    }
                }
            }
            catch {}
            return info;
        }

        public static bool IsNewerVersion(string currentVer, string remoteVer)
        {
            try
            {
                Version vCur = new Version(currentVer.TrimStart('v', 'V'));
                Version vRem = new Version(remoteVer.TrimStart('v', 'V'));
                return vRem > vCur;
            }
            catch
            {
                return string.Compare(remoteVer, currentVer, StringComparison.OrdinalIgnoreCase) > 0;
            }
        }

        public static void CheckForUpdatesAsync(string url, Action<UpdateInfo, string> callback)
        {
            try
            {
                ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072 | (SecurityProtocolType)768 | SecurityProtocolType.Tls;
            }
            catch {}

            BackgroundWorker bw = new BackgroundWorker();
            bw.DoWork += (s, e) =>
            {
                try
                {
                    using (WebClient client = new WebClient())
                    {
                        client.Headers.Add("User-Agent", "ClientProjectFolderGenerator/" + CURRENT_VERSION);
                        string json = client.DownloadString(url);
                        UpdateInfo info = ParseJson(json);
                        e.Result = info;
                    }
                }
                catch (Exception ex)
                {
                    e.Result = ex;
                }
            };

            bw.RunWorkerCompleted += (s, e) =>
            {
                if (e.Result is UpdateInfo)
                {
                    UpdateInfo info = (UpdateInfo)e.Result;
                    if (!string.IsNullOrEmpty(info.Version) && IsNewerVersion(CURRENT_VERSION, info.Version))
                    {
                        callback(info, null);
                    }
                    else
                    {
                        callback(null, "UP_TO_DATE");
                    }
                }
                else if (e.Result is Exception)
                {
                    callback(null, ((Exception)e.Result).Message);
                }
                else
                {
                    callback(null, "UNKNOWN_ERROR");
                }
            };

            bw.RunWorkerAsync();
        }
    }

