        private void StartDownloadAndInstall()
        {
            if (string.IsNullOrWhiteSpace(updateInfo.DownloadUrl))
            {
                MessageBox.Show("Download URL is not available in update manifest.", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                return;
            }

            pnlInfo.Visible = false;
            pnlDownload.Visible = true;
            btnUpdate.Enabled = false;
            btnLater.Enabled = false;

            string tempFile = Path.Combine(Path.GetTempPath(), "Setup_ClientProjectGenerator_Update.exe");

            try
            {
                if (File.Exists(tempFile)) File.Delete(tempFile);
            }
            catch {}

            downloadClient = new WebClient();
            downloadClient.Headers.Add("User-Agent", "ClientProjectFolderGenerator/" + UpdateManager.CURRENT_VERSION);

            downloadClient.DownloadProgressChanged += (s, e) =>
            {
                prgDownload.Value = e.ProgressPercentage;
                lblPercent.Text = e.ProgressPercentage + "%";
                double mbReceived = e.BytesReceived / (1024.0 * 1024.0);
                double mbTotal = e.TotalBytesToReceive / (1024.0 * 1024.0);
                if (mbTotal > 0)
                {
                    lblDownloadStatus.Text = string.Format("Downloading: {0:F2} MB of {1:F2} MB", mbReceived, mbTotal);
                }
                else
                {
                    lblDownloadStatus.Text = string.Format("Downloading: {0:F2} MB", mbReceived);
                }
            };

            downloadClient.DownloadFileCompleted += (s, e) =>
            {
                if (e.Error != null)
                {
                    MessageBox.Show("Failed to download update: " + e.Error.Message, "Download Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    pnlDownload.Visible = false;
                    pnlInfo.Visible = true;
                    btnUpdate.Enabled = true;
                    btnLater.Enabled = true;
                    return;
                }

                if (e.Cancelled) return;

                lblDownloadStatus.Text = "✓ Download Complete! Launching Installer...";
                Application.DoEvents();

                try
                {
                    ProcessStartInfo psi = new ProcessStartInfo();
                    psi.FileName = tempFile;
                    psi.UseShellExecute = true;
                    Process.Start(psi);

                    // Gracefully exit current instance so the installer can update files smoothly
                    Application.Exit();
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Could not launch installer: " + ex.Message, "Launch Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    this.Close();
                }
            };

            try
            {
                downloadClient.DownloadFileAsync(new Uri(updateInfo.DownloadUrl), tempFile);
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error starting download: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                pnlDownload.Visible = false;
                pnlInfo.Visible = true;
                btnUpdate.Enabled = true;
                btnLater.Enabled = true;
            }
        }

        protected override void OnHandleCreated(EventArgs e)
        {
            base.OnHandleCreated(e);
            try
            {
                Icon ico = AppAssets.GetAppIcon();
                if (ico != null)
                {
                    SendMessage(this.Handle, WM_SETICON, (IntPtr)ICON_BIG, ico.Handle);
                    SendMessage(this.Handle, WM_SETICON, (IntPtr)ICON_SMALL, ico.Handle);
                }
            }
            catch {}
        }
    }

