            {
                SystemEvents.UserPreferenceChanged += SystemEvents_UserPreferenceChanged;
            }
            catch {}

            InitializeComponents();
            LoadConfig();
            UpdatePreview();
        }

        private void MainForm_FormClosed(object sender, FormClosedEventArgs e)
        {
            try
            {
                SystemEvents.UserPreferenceChanged -= SystemEvents_UserPreferenceChanged;
            }
            catch {}
        }

        private void SystemEvents_UserPreferenceChanged(object sender, UserPreferenceChangedEventArgs e)
        {
            if (savedThemeName.Contains("System Default"))
            {
                try
                {
                    this.BeginInvoke(new Action(() => {
                        ApplyTheme(AppTheme.GetSystemTheme());
                    }));
                }
                catch {}
            }
        }

        private void MainForm_Shown(object sender, EventArgs e)
        {
            if (!hasSeenGuide && showGuideOnStartup)
            {
                ShowUserGuide(true);
                hasSeenGuide = true;
                SaveConfig();
            }

            // Background Auto Update Check
            if (autoCheckUpdates)
            {
                PerformBackgroundUpdateCheck();
            }
        }

        private void PerformBackgroundUpdateCheck()
        {
            UpdateManager.CheckForUpdatesAsync(updateServerUrl, (info, err) =>
            {
                if (info != null)
                {
                    latestDiscoveredUpdate = info;
                    this.BeginInvoke(new Action(() =>
                    {
                        ShowUpdateBanner(info);
                    }));
                }
            });
        }

        private void ShowUpdateBanner(UpdateInfo info)
        {
            lblUpdateBannerText.Text = string.Format("🔔 Update v{0} is available with new features!", info.Version);
            pnlUpdateBanner.Visible = true;
        }

