        private void CheckForUpdatesManual()
        {
            Cursor.Current = Cursors.WaitCursor;
            UpdateManager.CheckForUpdatesAsync(updateServerUrl, (info, err) =>
            {
                Cursor.Current = Cursors.Default;
                if (info != null)
                {
                    latestDiscoveredUpdate = info;
                    ShowUpdateBanner(info);
                    using (UpdateDialogForm dlg = new UpdateDialogForm(info, currentTheme))
                    {
                        dlg.ShowDialog(this);
                    }
                }
                else if (err == "UP_TO_DATE")
                {
                    MessageBox.Show(
                        string.Format("✓ You are using the latest version of Client Project Folder Generator (v{0}).\n\nNo updates are required at this time.", UpdateManager.CURRENT_VERSION),
                        "Up to Date",
                        MessageBoxButtons.OK,
                        MessageBoxIcon.Information
                    );
                }
                else
                {
                    MessageBox.Show(
                        "Could not connect to update server or check for updates.\n\nPlease ensure you have an active internet connection.\n\nServer: " + updateServerUrl + "\nDetails: " + err,
                        "Update Check",
                        MessageBoxButtons.OK,
                        MessageBoxIcon.Warning
                    );
                }
            });
        }

        private void ConfigureUpdateUrl()
        {
            string prompt = "Enter your custom version.json URL (e.g., raw GitHub URL):";
            using (Form inputForm = new Form())
            {
                inputForm.Text = "Configure Update Server URL";
                inputForm.Size = new Size(520, 190);
                inputForm.StartPosition = FormStartPosition.CenterParent;
                inputForm.FormBorderStyle = FormBorderStyle.FixedDialog;
                inputForm.MaximizeBox = false;
                inputForm.MinimizeBox = false;
                inputForm.BackColor = currentTheme.FormBg;
                inputForm.ForeColor = currentTheme.TextPrimary;

