        private void BuildThemesMenu()
        {
            menuThemes.DropDownItems.Clear();
            foreach (AppTheme t in themesList)
            {
                ToolStripMenuItem item = new ToolStripMenuItem(t.Name);
                bool isChecked = false;
                if (savedThemeName.Contains("System Default") && t.Name.Contains("System Default"))
                    isChecked = true;
                else if (savedThemeName == t.Name)
                    isChecked = true;

                item.Checked = isChecked;
                item.ForeColor = currentTheme.MenuText;
                item.BackColor = currentTheme.MenuBg;
                
                string targetThemeName = t.Name;
                item.Click += (s, e) => {
                    savedThemeName = targetThemeName;
                    if (targetThemeName.Contains("System Default"))
                    {
                        ApplyTheme(AppTheme.GetSystemTheme());
                    }
                    else
                    {
                        foreach (AppTheme th in themesList)
                        {
                            if (th.Name == targetThemeName)
                            {
                                ApplyTheme(th);
                                break;
                            }
                        }
                    }
                    SaveConfig();
                };
                menuThemes.DropDownItems.Add(item);
            }
        }

        public void ApplyTheme(AppTheme theme)
