        private string GetFormattedDate(string format)
        {
            DateTime now = DateTime.Now;
            switch (format)
            {
                case "YYYY-MM-DD": return now.ToString("yyyy-MM-dd");
                case "DD-MM-YYYY": return now.ToString("dd-MM-yyyy");
                case "YYYY.MM.DD": return now.ToString("yyyy.MM.dd");
                case "DD-MMM-YYYY": return now.ToString("dd-MMM-yyyy");
                case "YYYYMMDD": return now.ToString("yyyyMMdd");
                default: return now.ToString("yyyy-MM-dd");
            }
        }

        private string SanitizeFolderName(string name)
        {
            if (string.IsNullOrWhiteSpace(name)) return "";
            string invalid = new string(Path.GetInvalidFileNameChars()) + new string(Path.GetInvalidPathChars());
            foreach (char c in invalid)
            {
                name = name.Replace(c, '_');
            }
            return name.Trim();
        }

        private void UpdatePreview()
        {
            string cName = SanitizeFolderName(txtClient.Text);
            if (string.IsNullOrWhiteSpace(cName)) cName = "[Client]";

            string pName = SanitizeFolderName(txtProj.Text);
            string dStr = chkUseDate.Checked ? GetFormattedDate(cmbDateFormat.SelectedItem != null ? cmbDateFormat.SelectedItem.ToString() : "YYYY-MM-DD") : "";

            List<string> parts = new List<string>();
            if (!string.IsNullOrEmpty(dStr)) parts.Add(dStr);
            if (!string.IsNullOrEmpty(pName)) parts.Add(pName);

            string subFolder = parts.Count > 0 ? string.Join(" - ", parts.ToArray()) : (chkUseDate.Checked ? "[Date - Project]" : "");
            string root = !string.IsNullOrWhiteSpace(txtRoot.Text) ? txtRoot.Text.TrimEnd('\\') : @"[Root Directory]";

            if (!string.IsNullOrEmpty(subFolder))
            {
                lblPreview.Text = string.Format(@"{0}\\{1}\\{2}\\", root, cName, subFolder);
            }
            else
            {
                lblPreview.Text = string.Format(@"{0}\\{1}\\", root, cName);
            }
        }

        private void CreateProject()
        {
            string clientName = SanitizeFolderName(txtClient.Text);
            string projTitle = SanitizeFolderName(txtProj.Text);
            string rootPath = txtRoot.Text.Trim();
            string templatePath = txtTemplate.Text.Trim();
            string dateFormat = cmbDateFormat.SelectedItem != null ? cmbDateFormat.SelectedItem.ToString() : "YYYY-MM-DD";

            if (string.IsNullOrWhiteSpace(clientName))
            {
                MessageBox.Show("Please enter a Client Name.", "Missing Client Name", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                txtClient.Focus();
                return;
            }

            if (string.IsNullOrWhiteSpace(rootPath))
            {
                MessageBox.Show("Please click '...' and select your Root Projects Directory where client folders will be saved.", "Missing Root Directory", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            try
            {
                if (!Directory.Exists(rootPath))
                {
                    DialogResult res = MessageBox.Show("Root folder does not exist:\n" + rootPath + "\n\nDo you want to create it?", "Create Root Folder", MessageBoxButtons.YesNo, MessageBoxIcon.Question);
                    if (res == DialogResult.Yes)
                    {
                        Directory.CreateDirectory(rootPath);
                    }
                    else
                    {
                        return;
                    }
                }

                // 1. Client Folder
                string clientFolder = Path.Combine(rootPath, clientName);
                if (!Directory.Exists(clientFolder))
                {
                    Directory.CreateDirectory(clientFolder);
                }

                // 2. Project Subfolder
                string dateStr = chkUseDate.Checked ? GetFormattedDate(dateFormat) : "";
                List<string> folderParts = new List<string>();
                if (!string.IsNullOrEmpty(dateStr)) folderParts.Add(dateStr);
                if (!string.IsNullOrEmpty(projTitle)) folderParts.Add(projTitle);

                string subFolderName = folderParts.Count > 0 ? string.Join(" - ", folderParts.ToArray()) : (chkUseDate.Checked ? dateStr : "Project");
                string finalProjectFolder = Path.Combine(clientFolder, subFolderName);

                if (!Directory.Exists(finalProjectFolder))
                {
                    Directory.CreateDirectory(finalProjectFolder);
                }

                // 3. 5 Standard Subfolders
                string[] standardFolders = new string[]
                {
                    "01.Project Files",
                    "02.Footage",
                    "03.Essential Elements",
                    "04.Sounds",
                    "05.Final Exports"
                };

                foreach (string sf in standardFolders)
                {
                    string targetSub = Path.Combine(finalProjectFolder, sf);
                    if (!Directory.Exists(targetSub))
                    {
                        Directory.CreateDirectory(targetSub);
                    }
                }

                // 4. Copy Template Assets if enabled
                bool copiedTemplate = false;
                if (chkCopyTemplate.Checked && !string.IsNullOrWhiteSpace(templatePath) && Directory.Exists(templatePath))
                {
                    CopyDirectoryContents(templatePath, finalProjectFolder);
                    copiedTemplate = true;
                }

                lastCreatedPath = finalProjectFolder;

                // Update Recent Clients
                if (!recentClients.Contains(clientName))
                {
                    recentClients.Insert(0, clientName);
                    if (recentClients.Count > 15) recentClients.RemoveAt(recentClients.Count - 1);

                    cmbRecent.Items.Clear();
                    cmbRecent.Items.Add("(Recent Clients)");
                    foreach (string c in recentClients) cmbRecent.Items.Add(c);
                    cmbRecent.SelectedIndex = 0;
                }

                SaveConfig();

                // 5. Open Explorer if enabled
                if (chkOpenExplorer.Checked)
                {
                    try
                    {
                        Process.Start("explorer.exe", finalProjectFolder);
                    }
                    catch {}
                }

                string msg = string.Format(
                    "✓ Project created successfully!\n\n" +
                    "Client: {0}\n" +
                    "Path: {1}\n\n" +
                    "• 5 Standard Subfolders generated\n" +
                    (copiedTemplate ? "• Template assets copied successfully\n" : "") +
                    "\nHappy Editing & Designing!",
                    clientName,
                    finalProjectFolder
                );

                MessageBox.Show(msg, "Project Folder Ready", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error creating project folder: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private void CopyDirectoryContents(string sourceDir, string destDir)
        {
            DirectoryInfo dir = new DirectoryInfo(sourceDir);
            foreach (FileInfo file in dir.GetFiles())
            {
                string targetFilePath = Path.Combine(destDir, file.Name);
                if (!File.Exists(targetFilePath))
                {
                    file.CopyTo(targetFilePath, false);
                }
            }

            foreach (DirectoryInfo subDir in dir.GetDirectories())
            {
                string targetSubDirPath = Path.Combine(destDir, subDir.Name);
                if (!Directory.Exists(targetSubDirPath))
                {
                    Directory.CreateDirectory(targetSubDirPath);
                }
                CopyDirectoryContents(subDir.FullName, targetSubDirPath);
            }
        }

