        private void LoadConfig()
        {
            try
            {
                if (File.Exists(configPath))
                {
                    string json = File.ReadAllText(configPath);

                    Match mSeen = Regex.Match(json, "\"hasSeenGuide\"\\s*:\\s*(true|false)");
                    if (mSeen.Success) hasSeenGuide = mSeen.Groups[1].Value.ToLower() == "true";

                    Match mShowGuide = Regex.Match(json, "\"showGuideOnStartup\"\\s*:\\s*(true|false)");
                    if (mShowGuide.Success) showGuideOnStartup = mShowGuide.Groups[1].Value.ToLower() == "true";

                    Match mAutoUp = Regex.Match(json, "\"autoCheckUpdates\"\\s*:\\s*(true|false)");
                    if (mAutoUp.Success) autoCheckUpdates = mAutoUp.Groups[1].Value.ToLower() == "true";

                    Match mUpUrl = Regex.Match(json, "\"updateServerUrl\"\\s*:\\s*\"(.*?)\"");
                    if (mUpUrl.Success) updateServerUrl = Regex.Unescape(mUpUrl.Groups[1].Value);

                    Match mTheme = Regex.Match(json, "\"theme\"\\s*:\\s*\"(.*?)\"");
                    if (mTheme.Success)
                    {
                        savedThemeName = Regex.Unescape(mTheme.Groups[1].Value);
                        if (savedThemeName.Contains("System Default"))
                        {
                            ApplyTheme(AppTheme.GetSystemTheme());
                        }
                        else
                        {
                            foreach (AppTheme t in themesList)
                            {
                                if (t.Name.Equals(savedThemeName, StringComparison.OrdinalIgnoreCase))
                                {
                                    ApplyTheme(t);
                                    break;
                                }
                            }
                        }
                    }

                    Match mRoot = Regex.Match(json, "\"rootDir\"\\s*:\\s*\"(.*?)\"");
                    if (mRoot.Success) txtRoot.Text = Regex.Unescape(mRoot.Groups[1].Value);

                    Match mTemplate = Regex.Match(json, "\"templateDir\"\\s*:\\s*\"(.*?)\"");
                    if (mTemplate.Success) {
                        string t = Regex.Unescape(mTemplate.Groups[1].Value);
                        if (Directory.Exists(t)) {
                            txtTemplate.Text = t;
                        }
                    }

                    Match mDateFormat = Regex.Match(json, "\"dateFormat\"\\s*:\\s*\"(.*?)\"");
                    if (mDateFormat.Success) {
                        string df = mDateFormat.Groups[1].Value;
                        int idx = cmbDateFormat.Items.IndexOf(df);
                        if (idx >= 0) cmbDateFormat.SelectedIndex = idx;
                    }

                    Match mUseDate = Regex.Match(json, "\"useDate\"\\s*:\\s*(true|false)");
                    if (mUseDate.Success) chkUseDate.Checked = mUseDate.Groups[1].Value.ToLower() == "true";

                    Match mCopy = Regex.Match(json, "\"copyTemplate\"\\s*:\\s*(true|false)");
                    if (mCopy.Success) chkCopyTemplate.Checked = mCopy.Groups[1].Value.ToLower() == "true";

                    Match mOpen = Regex.Match(json, "\"openExplorer\"\\s*:\\s*(true|false)");
                    if (mOpen.Success) chkOpenExplorer.Checked = mOpen.Groups[1].Value.ToLower() == "true";

                    Match mClients = Regex.Match(json, "\"recentClients\"\\s*:\\s*\\[(.*?)\\]", RegexOptions.Singleline);
                    if (mClients.Success) {
                        recentClients.Clear();
                        cmbRecent.Items.Clear();
                        cmbRecent.Items.Add("(Recent Clients)");
                        MatchCollection matches = Regex.Matches(mClients.Groups[1].Value, "\"(.*?)\"");
                        foreach (Match match in matches) {
                            string c = Regex.Unescape(match.Groups[1].Value).Trim();
                            if (!string.IsNullOrEmpty(c) && !recentClients.Contains(c)) {
                                recentClients.Add(c);
                                cmbRecent.Items.Add(c);
                            }
                        }
                        cmbRecent.SelectedIndex = 0;
                    }
                }
            }
            catch {}
        }

        private void SaveConfig()
        {
            try
            {
                List<string> lines = new List<string>();
                lines.Add("{");
                lines.Add("  \"hasSeenGuide\": " + (hasSeenGuide ? "true" : "false") + ",");
                lines.Add("  \"showGuideOnStartup\": " + (showGuideOnStartup ? "true" : "false") + ",");
                lines.Add("  \"autoCheckUpdates\": " + (autoCheckUpdates ? "true" : "false") + ",");
                lines.Add("  \"updateServerUrl\": \"" + updateServerUrl.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\",");
                lines.Add("  \"theme\": \"" + savedThemeName.Replace("\"", "\\\"") + "\",");
                lines.Add("  \"rootDir\": \"" + txtRoot.Text.Replace("\\", "\\\\") + "\",");
                lines.Add("  \"templateDir\": \"" + txtTemplate.Text.Replace("\\", "\\\\") + "\",");
                lines.Add("  \"dateFormat\": \"" + (cmbDateFormat.SelectedItem != null ? cmbDateFormat.SelectedItem.ToString() : "YYYY-MM-DD") + "\",");
                lines.Add("  \"useDate\": " + (chkUseDate.Checked ? "true" : "false") + ",");
                lines.Add("  \"copyTemplate\": " + (chkCopyTemplate.Checked ? "true" : "false") + ",");
                lines.Add("  \"openExplorer\": " + (chkOpenExplorer.Checked ? "true" : "false") + ",");

                List<string> clientEntries = new List<string>();
                foreach (string c in recentClients)
                {
                    clientEntries.Add("    \"" + c.Replace("\"", "\\\"") + "\"");
                }
                lines.Add("  \"recentClients\": [\n" + string.Join(",\n", clientEntries.ToArray()) + "\n  ]");
                lines.Add("}");

                File.WriteAllText(configPath, string.Join("\n", lines.ToArray()));
            }
            catch {}
        }
    }

